// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address caller, address recipient) public {
        vm.assume(caller != address(this));
        vm.deal(address(c), 1 ether);
        vm.prank(caller);
        bool ok = true;
        try c.withdrawAll(recipient) {} catch { ok = false; }
        assertTrue(!ok);
    }
}
